use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        // Length is preserved.
        new_list.len() == list.len(),
        // The result is a rotation: elements from [n..len) come first...
        forall|i: int|
            0 <= i && i < (list.len() - n) as int ==>
                new_list[i] == list[(i + n as int) as int],
        // ...followed by elements from [0..n).
        forall|i: int|
            0 <= i && i < n as int ==>
                new_list[(list.len() - n) as int + i] == list[i],
{
    let len = list.len();
    assert!(len > 0, "list must be non-empty");
    assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[n..]);
    new_list.extend_from_slice(&list[..n]);
    new_list
}

} // verus!